<div class="card"><div class="card-body p-4"><span class="badge text-bg-success"><?= esc($trail['difficulty']) ?></span><h1 class="mt-2"><?= esc($trail['name']) ?></h1><p class="muted"><?= esc($trail['location']) ?> · <?= esc($trail['distance_km']) ?> km</p><p><?= nl2br(esc($trail['description'])) ?></p><div class="d-flex flex-wrap gap-2"><a class="btn btn-outline-secondary" href="<?= site_url('trails/'.$trail['id'].'/edit') ?>">Edit</a><button class="btn btn-outline-danger" onclick="if(confirm('Delete this trail?'))document.getElementById('deleteForm').submit()">Delete</button><button id="fav" class="btn btn-forest">♡ Save favourite</button><a class="btn btn-outline-secondary" href="<?= site_url('reviews/'.$trail['id']) ?>">View reviews</a></div><form id="deleteForm" method="post" action="<?= site_url('trails/'.$trail['id'].'/delete') ?>"><?= csrf_field() ?></form><div id="notice" class="small mt-2" aria-live="polite"></div></div></div>
<script>document.getElementById('fav').addEventListener('click',async()=>{const r=await fetch('<?= site_url('api/favourites/'.$trail['id']) ?>',{method:'POST',headers:{'X-Requested-With':'XMLHttpRequest','<?= csrf_header() ?>':'<?= csrf_hash() ?>'}});const d=await r.json();document.getElementById('fav').textContent=d.saved?'♥ Saved':'♡ Save favourite';document.getElementById('notice').textContent=d.error||'Favourite updated.';});</script>
